mapper.select:
SELECT COUNT(1) > 0
FROM user_resource_auth
WHERE user_id = #{userId}
  AND resource_type = #{resourceType}
  AND resource_id = #{resourceId}
  AND status = 1
  AND (expire_at IS NULL OR expire_at > NOW())

mapper.update:
UPDATE user_resource_auth
SET status = 0,
    updated_at = NOW()
WHERE user_id = #{userId}
  AND resource_type = #{resourceType}
  AND status = 1
